/// <summary>
///     The <c>AVACustFreeInvoiceFrm_CustInvoiceTableDs_Extension</c> class is the extension for <c>CustFreeInvoice</c>
/// </summary>
[ExtensionOf(formDataSourceStr(CustFreeInvoice, CustInvoiceTable))]
final class AVACustFreeInvoiceFrm_CustInvoiceTableDs_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>initValue</c> method.
/// </summary>
public void initValue()
{
    CustInvoiceTable locCustInvoiceTable;

    next initValue();

    locCustInvoiceTable = this.cursor();

    if(element.frmBonusMode)
    {
        locCustInvoiceTable.AVABonusInvoice = NoYes::Yes;
        locCustInvoiceTable.modifiedField(fieldnum(CustInvoiceTable, AVABonusInvoice));
    }
}

/// <summary>
///     AVA <c>active</c> method.
/// </summary>
/// <returns>
///     <c>int</c> as return value
/// </returns>
public int active()
{
    int retVal;

    retVal                      = next active();
    FormRun                     formRun = this.formRun();
    FormDataSource              lineDS = formRun.dataSource(formDataSourceStr(CustFreeInvoice,CustInvoiceLine));
    lineDS.allowEdit(true);

    FormDataSource              bonusCorDS = formRun.dataSource(formDataSourceStr(CustFreeInvoice,AVACustInvoiceLineAdjust));
    bonusCorDS.allowEdit(true);

    element.frmCustInvoiceTable = this.cursor();
    this.allowEdit(true);
    element.avaSetFormControls();


    return retVal;
}
